{
  "description": "The creature is a large, quadrupedal, tortoise-like animal shown in right-facing side profile standing on a small patch of sparse grass and bare dirt against a plain light background. It has a high, domed carapace covering its back and sides, colored in mottled browns and tans with dark radiating striations and prominent raised, pyramidal scutes. Its head and long, thick neck are extended forward and slightly upward and are covered in wrinkled, pebbly reptilian skin with a blunt beaked mouth and a dark eye. Its four thick, columnar legs beneath the shell are covered in long, shaggy, light tan to beige fur, with scaly, clawed feet at the ground, and a small, short, pointed scaly tail protrudes from beneath the rear edge of the shell among the fur at the back.",
  "parts": [
    {
      "part": "head",
      "looks_like": "tortoise-like with rough polygonal scales on the top and sides, a blunt beaked snout with nostrils at the tip, a small dark eye with scaly eyelids, and a slightly open mouth showing the lower jaw",
      "where": "at the far front end of the long neck, facing to the right and slightly up"
    },
    {
      "part": "legs",
      "looks_like": "four thick, pillar-like walking legs covered in long, shaggy, light beige to tan hair, with larger overlapping pointed horny scales visible on the front of the forelimbs",
      "where": "under the shell, two on the near side fully visible and two on the far side partially visible behind them, supporting the body above the ground"
    },
    {
      "part": "feet",
      "looks_like": "broad, scaly feet with pebbly skin and three to four blunt, dark, curved claws on each foot",
      "where": "at the bottom ends of each of the four legs, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, conical and pointed, covered in small pointed scales, with long shaggy fur around its base",
      "where": "at the rear of the body, protruding from under the back edge of the shell on the left side of the image"
    },
    {
      "part": "shell",
      "looks_like": "large, high-domed carapace with strongly raised, pyramidal scutes and flared, serrated rear marginal scutes, colored in bands of dark brown, medium brown and tan",
      "where": "covering the dorsal and lateral parts of the body from behind the neck to above the tail and down to above the legs"
    },
    {
      "part": "plates",
      "looks_like": "large polygonal scutes/plates with keeled, pyramid-shaped centers and concentric growth ridges, separated by light seams",
      "where": "tiled across the entire shell surface, forming the carapace"
    },
    {
      "part": "scales",
      "looks_like": "small, polygonal, pebbly scales on the head, neck, feet and tail, and larger, overlapping, pointed, claw-like scales on the front of the forelimbs",
      "where": "covering the head, the long wrinkled neck, the lower legs and feet, the tail, and in a dense row on the anterior side of the front legs"
    },
    {
      "part": "markings",
      "looks_like": "dark brown to blackish radiating striations and growth lines on each shell plate, and mottled tan and brown patterning on the shell and skin",
      "where": "on each scute of the shell and subtly on the skin of the neck and legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "tortoise"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
